const KEY='twinlakes-v1';
const CV=2;
const DEF=[['1W',180],['3W',150],['5W',150],['4U',160],['5U',140],['6I',130],['7I',130],['8I',120],['9I',105],['PW',100],['AW',85],['SW',60]];
const U={view:'hole',sel:null,arm:false};
let R={cv:CV,cur:1,tee:'w',holes:{},clubs:DEF.map(c=>({name:c[0],dist:c[1]})),gps:false};
let G={watch:null,y:null,acc:null,at:0,err:''};
const app=document.getElementById('app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function say(t,ms){const e=document.querySelector('#status span');e.textContent=t;clearTimeout(say.t);if(ms)say.t=setTimeout(()=>e.textContent='',ms)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(R))}catch(e){say('この端末に保存できません。',4000)}}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&x.holes){R=Object.assign(R,x);if(x.cv!==CV){R.cv=CV;R.clubs=DEF.map(c=>({name:c[0],dist:c[1]}));save()}}}catch(e){}}
function H(n){return R.holes[n]||(R.holes[n]={shots:[],rem:null,putts:0,green:false})}
const BUILTIN={id:'twinlakes',name:'ツインレイクスCC',base:'w',tees:[['b','Black'],['w','White'],['g','Green']],notes:['3番・17番（約130Y）→ 4U','12番（約110Y）→ 7I以上'],holes:D0};
D0.forEach(d=>{d.y={b:d.b,w:d.w,g:d.g}});
let D=D0,CO=BUILTIN,TN={},COURSE=BUILTIN.name;
function courseList(){return BUILT.concat(Object.keys(R.courses||{}).map(k=>R.courses[k]))}
function applyCourse(){CO=(R.courses&&R.courses[R.course])||BUILT.find(c=>c.id===R.course)||BUILTIN;if(CO===BUILTIN)R.course='twinlakes';const fx=gFix();D=CO.holes.map((h,i)=>fx[i+1]?Object.assign({},h,{gc:fx[i+1]}):h);TN={};CO.tees.forEach(t=>{TN[t[0]]=t[1]});if(!TN[R.tee])R.tee=CO.base;COURSE=CO.name;document.title=CO.name+' 攻略'}
function cleanStr(v,max){return String(v==null?'':v).replace(/[<>&"'`\\]/g,'').replace(/\s+/g,' ').trim().slice(0,max)}
function okPos(p){return Array.isArray(p)&&p.length===2&&typeof p[0]==='number'&&typeof p[1]==='number'&&Math.abs(p[0])<=90&&Math.abs(p[1])<=180}
function parseCourse(txt){let j;try{j=JSON.parse(txt)}catch(e){throw new Error('コースデータとして読めません。クロコが作った文をそのまま貼り付けてください。')}
  const name=cleanStr(j.name,30).replace(/ /g,'');if(!name)throw new Error('コース名がありません。');
  if(!Array.isArray(j.holes)||j.holes.length!==18)throw new Error('18ホール分のデータが必要です（今は'+(Array.isArray(j.holes)?j.holes.length:0)+'ホール）。');
  const tees=(Array.isArray(j.tees)?j.tees:[]).filter(t=>Array.isArray(t)&&/^[a-z0-9]{1,8}$/.test(String(t[0]))).slice(0,5).map(t=>[String(t[0]),cleanStr(t[1],12)||String(t[0])]);if(!tees.length)throw new Error('ティーの一覧（tees）がありません。');
  const base=tees.some(t=>t[0]===j.base)?j.base:tees[0][0];
  const holes=j.holes.map((h,i)=>{const p=Number(h&&h.p);if(!(p>=3&&p<=6))throw new Error((i+1)+'番のパー（p）が正しくありません。');const y={};tees.forEach(t=>{const v=Number(h.y&&h.y[t[0]]);if(v>=30&&v<=800)y[t[0]]=Math.round(v)});if(y[base]==null)throw new Error((i+1)+'番の'+base+'ティーのヤードがありません。');const o={p,y};const hc=Number(h.hc);if(hc>=1&&hc<=18)o.hc=Math.round(hc);if(okPos(h.gc))o.gc=h.gc;if(okPos(h.tc))o.tc=h.tc;['club','risk','aim','green'].forEach(k=>{const v=cleanStr(h[k],120);if(v)o[k]=v});return o});
  return{id:'c'+Date.now(),name,base,tees,holes,notes:(Array.isArray(j.notes)?j.notes:[]).slice(0,6).map(x=>cleanStr(x,60)).filter(Boolean)}}
function courseJson(){return JSON.stringify({name:CO.name,base:CO.base,tees:CO.tees,notes:CO.notes||[],holes:D.map(d=>{const o={p:d.p,hc:d.hc,y:d.y};['gc','tc','club','risk','aim','green'].forEach(k=>{if(d[k]!=null)o[k]=d[k]});return o})})}
function courseBox(){const L=courseList(),gps=D.filter(d=>d.gc).length,tee=D.filter(d=>d.tc).length;return'<section class="card"><div class="h">コース</div><select id="csel" class="input" aria-label="コース選択" style="width:100%">'+L.map(c=>'<option value="'+c.id+'"'+(c.id===CO.id?' selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select><p class="note">今のコース：グリーンの座標 '+gps+'/18、ティーの座標 '+tee+'/18。座標があるホールだけ、GPSの残り距離と旗の図が使えます。</p><div class="h">コースを追加</div><textarea id="cjson" rows="3" placeholder="クロコが作ったコースデータを貼り付け" aria-label="コースデータ" style="width:100%;font-size:13px;background:var(--bg);color:var(--fg);border:1px solid var(--line);border-radius:6px"></textarea><div class="two"><button class="act" data-cadd="1">追加する</button><button class="ghost" data-ccopy="1">今のコースをコピー</button></div>'+(BUILT.indexOf(CO)<0?'<button class="link" data-cdel="1">'+(U.cdel?'もう一度押すと「'+esc(CO.name)+'」を消します':'このコースを消す')+'</button>':'')+'</section>'}
function setCourse(id){if(id===CO.id)return true;if(roundSummary().n){say('記録中のラウンドがあります。「スコア」で履歴に保存し、「新しいラウンドを始める」を押してから切り替えてください。',7000);return false}R.course=id;R.holes={};R.cur=1;R.rid=null;applyCourse();G.y=null;save();return true}
function picCard(n){return CO===BUILTIN?'<section class="card">'+picBox(n)+'</section>':''}
function teeLate(n,p){const d=D[n-1];return!!(p&&d.tc&&G.y!=null&&yardsTo(p,d.tc)>90&&G.y<yards(n)-50)}
function yards(n){const y=D[n-1].y;return y[R.tee]!=null?y[R.tee]:y[CO.base]}
function rem(n){const h=H(n);return h.rem==null?yards(n):h.rem}
function strokes(h){return h.quick!=null?h.quick:h.shots.reduce((a,s)=>a+1+(s.pen||0),0)+h.putts}
function touched(h){return h.shots.length>0||h.putts>0||h.quick!=null}
function byDist(){const o=c=>R.clubs.indexOf(c);return R.clubs.filter(c=>c.dist>0).slice().sort((a,b)=>a.dist-b.dist||o(b)-o(a))}
function yardsTo(a,b){const r=Math.PI/180,E=6371000,dl=(b[0]-a[0])*r,dg=(b[1]-a[1])*r,x=Math.sin(dl/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dg/2)**2;return Math.round(2*E*Math.asin(Math.sqrt(x))/0.9144)}
const LIE={fw:'FW',light:'浅いラフ',deep:'深いラフ',bunker:'バンカー'};
function lieOf(h){return h.lie||'fw'}
function ng(c,h){const k=lieOf(h);if(k==='light')return /1W|3W|5W|6I/.test(c.name);if(k==='deep')return !/AW|SW/.test(c.name);if(k==='bunker')return c.name!=='SW';return false}
function eff(c,h){const k=lieOf(h),f=k==='light'?.9:k==='deep'||k==='bunker'?.5:1;return f===1?c.dist:Math.round(c.dist*f/5)*5}
function lieBox(h){return '<section class="card"><div class="h">球の場所</div><div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px">'+Object.keys(LIE).map(k=>'<button style="font-size:13px;padding:0 1px;white-space:nowrap" class="'+(lieOf(h)===k?'act':'ghost')+'" data-lie="'+k+'" aria-pressed="'+(lieOf(h)===k)+'">'+LIE[k]+'</button>').join('')+'</div><p class="note">球に着いたら、今の場所を押します。番手の提案が変わり、GPSがオンなら前の打の飛距離も記録します。</p></section>'}
function atTee(n){return H(n).shots.every(x=>x.r==='miss')&&nearTee(n)}
