function nearTee(n){const d=D[n-1],p=fixPos();return!p||!d.tc||yardsTo(p,d.tc)<=90}
function gFix(){return(R.fix&&R.fix[CO.id])||{}}
function greenFixBox(n){const f=gFix()[n];return'<button class="ghost" data-gfix="1">ここをグリーン中央として登録</button>'+(f?'<button class="link" data-gunfix="1">登録を取り消す（元の位置に戻す）</button>':'')+'<p class="note">'+(f?'このホールのグリーンは、登録した位置を使っています。':'残り距離がずれていた時だけ押します。グリーンの真ん中に立って押すと、次回からその位置で測ります。')+'</p>'}
function courseMap(n){const V=D.map((d,i)=>[d,i]).filter(x=>x[0].tc&&x[0].gc);if(!V.length)return'<p class="note">このコースは座標が未登録のため、図を出せません。</p>';const o=V[0][0].gc,P=[];V.forEach(x=>{P.push(xy(x[0].tc,o),xy(x[0].gc,o))});if(CO.ch){const q=xy(CO.ch,o);P.push(q,[q[0],q[1]-45])}const me=meNow(),mp=me?xy(me,o):null;const all=P.slice();if(mp&&P.some(q=>Math.hypot(q[0]-mp[0],q[1]-mp[1])<600))all.push(mp);const vb=svgFit(all,.6),s=Math.max(vb[2]/340,vb[3]/420),Y=p=>-p[1];let g2='';
  (CO.ponds||[]).forEach(q=>{const c=xy(q,o);g2+='<circle cx="'+c[0].toFixed(1)+'" cy="'+Y(c).toFixed(1)+'" r="'+q[2]+'" fill="#2f6fb5" opacity=".8"/>'});
  if(CO.ch){const c=xy(CO.ch,o);g2+='<rect x="'+(c[0]-11*s).toFixed(1)+'" y="'+(Y(c)-8*s).toFixed(1)+'" width="'+(22*s).toFixed(1)+'" height="'+(16*s).toFixed(1)+'" fill="#6b4a2b"/><text x="'+c[0].toFixed(1)+'" y="'+(Y(c)+20*s).toFixed(1)+'" text-anchor="middle" font-size="'+(10*s).toFixed(1)+'" fill="#3b2a18">クラブハウス</text>'}
  V.forEach(v=>{const d=v[0],i=v[1],a=xy(d.tc,o),b=xy(d.gc,o),on=i+1===n,c=on?'#0b6bcb':(i<9?'#c9a400':'#2a9bb0');g2+='<line x1="'+a[0].toFixed(1)+'" y1="'+Y(a).toFixed(1)+'" x2="'+b[0].toFixed(1)+'" y2="'+Y(b).toFixed(1)+'" stroke="'+c+'" stroke-width="'+((on?8:5)*s).toFixed(1)+'" stroke-linecap="round" opacity="'+(on?1:.75)+'"/><rect x="'+(a[0]-4*s).toFixed(1)+'" y="'+(Y(a)-4*s).toFixed(1)+'" width="'+(8*s).toFixed(1)+'" height="'+(8*s).toFixed(1)+'" fill="#fff" stroke="#333" stroke-width="'+(1*s).toFixed(1)+'"/>'});
  V.forEach(v=>{const d=v[0],i=v[1],b=xy(d.gc,o),on=i+1===n;g2+='<circle cx="'+b[0].toFixed(1)+'" cy="'+Y(b).toFixed(1)+'" r="'+((on?11:9)*s).toFixed(1)+'" fill="'+(on?'#0b4f99':'#d6281f')+'" stroke="#fff" stroke-width="'+(1.5*s).toFixed(1)+'"/><text x="'+b[0].toFixed(1)+'" y="'+(Y(b)+4*s).toFixed(1)+'" text-anchor="middle" font-size="'+((on?12:10.5)*s).toFixed(1)+'" font-weight="700" fill="#fff">'+(i+1)+'</text>'});
  if(mp&&all.indexOf(mp)>=0)g2+=flag(mp[0],Y(mp),'#d63b2f',s*1.4);
  const ctr=CO.ch||V[0][0].gc;
  return'<svg viewBox="'+vb.map(v=>v.toFixed(1)).join(' ')+'" style="display:block;width:100%;max-height:440px;background:#e3ecd9;border-radius:6px" role="img" aria-label="コース全体の位置関係。上が北">'+g2+'</svg><p class="note">上が北。丸い数字がグリーン、白い四角がティー。黄がOUT、水色がIN、青が今のホール。'+(CO.ponds?'青い丸は池のおおよその位置。':'')+(mp?(all.indexOf(mp)>=0?'赤い旗が現在地。':'現在地はコースの外です。'):'GPSをオンにすると現在地に赤い旗を立てます。')+'</p><a class="ghost" style="display:block;text-align:center;padding:10px;border:1px solid var(--line);border-radius:6px;color:var(--fg);text-decoration:none" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+ctr[0]+','+ctr[1]+'">Googleマップで開く（通信が必要）</a>'}

function planFw(r,l){const a=l.filter(c=>!/1W|3W/.test(c.name));if(!a.length)return null;const seqOf=u=>{const q=[];let x=r;while(x>30&&q.length<5){const f=a.find(c=>c.dist>=x&&c.dist<=u.dist);if(f){q.push(f.name);x=0;break}q.push(u.name);x-=u.dist}if(x>0)q.push('寄せ');return q};let best=null;['7I','5U'].map(nm=>a.find(c=>c.name===nm)).filter(Boolean).concat([a[Math.max(0,a.length-3)]]).forEach(u=>{const q=seqOf(u);if(!best||q.length<best.q.length)best={u,q}});return best}
function unfinished(n){const h=R.holes[n];if(!h||!touched(h))return false;const p=D[n-1].p;if(h.quick!=null)return h.quick<p-1;return !h.green||h.putts===0||strokes(h)<p-1}
function suggest(n){const s=suggest0(n),d=D[n-1];if(!H(n).green&&atTee(n)){if(d.aim&&s.n.indexOf(d.aim)<0)s.n=d.aim+(s.n?'　'+s.n:'');if(d.plus)s.n+=' 池越えのため、'+d.plus+'Y足して選んでいます。'}return s}
function suggest0(n){
  const h=H(n),d=D[n-1],r=rem(n)+(d.plus&&!h.green&&atTee(n)?d.plus:0);
  if(h.green)return{c:'パター',n:'カップをオーバーしない強さで。',rec:null};
  if(atTee(n)&&d.club&&!(R.tee!==CO.base&&d.p===3))return{c:d.club,n:(d.aim||'')+(R.tee===CO.base?'':' ※攻略文は'+TN[CO.base]+'基準です。'),rec:d.club};
  if(atTee(n)&&!d.club&&d.p>=4&&R.clubs.some(c=>c.name==='1W'))return{c:'1W',n:d.aim?'':'フェアウェイの広いほうへ。曲げないことを優先します。',rec:'1W'};
  const l=byDist();if(!l.length)return{c:'番手を登録',n:'「番手の距離」で登録してください。',rec:null};
  const k=lieOf(h);
  if(k==='bunker')return{c:'SWで出す',n:'距離より、1回で出すことを優先します。',rec:'SW'};
  if(k==='deep')return{c:'SWかAWで出す',n:'距離は考えません。フェアウェイへ戻せれば成功です。',rec:'SW'};
  if(r<=30)return{c:'SWかAWで寄せる',n:'グリーン中央へ。ピンは狙いません。',rec:'SW'};
  if(k==='light'){
    const a=l.filter(c=>!ng(c,h)),fit=a.find(c=>eff(c,h)>=r);
    if(fit)return{c:fit.name,n:'ラフのため目安'+eff(fit,h)+'Y。短く持って、コンパクトに振ります。',rec:fit.name};
    const u=a.find(c=>c.name==='7I')||a[a.length-1];
    return{c:'7Iか8Iで花道へ',n:'ラフから無理に届かせません。7Iは目安'+eff(u,h)+'Yで残り約'+Math.max(0,r-eff(u,h))+'Y。',rec:'7I'};
  }
  const fit=l.find(c=>c.dist>=r&&!/1W|3W/.test(c.name));
  if(fit)return{c:fit.name,n:'目安'+fit.dist+'Y。池とバンカーを避ける番手を優先します。',rec:fit.name};
  if(d.p===3&&atTee(n)){const u3=l.filter(c=>c.name!=='1W').pop();if(u3)return{c:u3.name,n:'届く番手がありません。いちばん飛ぶ番手で、危険の少ない側を狙います。',rec:u3.name}}
  const pl=planFw(r,l),u=pl?pl.u:(l.find(c=>c.name==='5U')||l[Math.max(0,l.length-3)]);return{c:u.name+'で運ぶ',n:(pl?'計画：'+pl.q.join(' → ')+'（'+pl.q.length+'回でグリーンへ）。':'')+'目安'+u.dist+'Yで残り約'+Math.max(0,r-u.dist)+'Y。曲げないことを優先します。',rec:u.name};
}
function gpsLine(){
  if(!R.gps)return'GPSはオフです。';if(G.err)return G.err;if(G.y==null)return'現在地を取得しています。';
  const age=Math.round((Date.now()-G.at)/1000);return'グリーン中央まで '+G.y+'Y（誤差 約'+Math.round(G.acc/0.9144)+'Y・'+age+'秒前）';
}
let IMGS=null,imgErr='';
const unb=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function openImgs(k){const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb(IMGX.i)},k,unb(IMGX.d));IMGS=JSON.parse(new TextDecoder().decode(pt))}
async function unlock(p){try{const bk=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:unb(IMGX.s),iterations:200000},bk,256);const k=await crypto.subtle.importKey('raw',bits,'AES-GCM',false,['decrypt']);await openImgs(k);imgErr='';try{localStorage.setItem(KEY+'-img',btoa(String.fromCharCode(...new Uint8Array(bits))))}catch(e){}}catch(e){imgErr='合言葉が違います。'}render()}
async function autoUnlock(){try{const r=localStorage.getItem(KEY+'-img');if(!r||typeof IMGX==='undefined')return;const k=await crypto.subtle.importKey('raw',unb(r),'AES-GCM',false,['decrypt']);await openImgs(k);render()}catch(e){}}
function picBox(n){if(typeof IMGX==='undefined')return'<p class="note">この版に画像は入っていません。攻略ページで見られます。</p>';if(!IMGS)return'<div class="h">画像の合言葉</div><div class="row"><input class="input" id="imgpw" type="password" autocomplete="off" aria-label="画像の合言葉"><button class="act" data-unlock="1">開く</button></div><p class="note">'+esc(imgErr||'最初の1回だけ入力します。スコアや番手は入力なしで使えます。')+'</p>';const m=IMGS[n-1],p=U.pic||'map',i=p==='map'?'<div class="pic map"><img style="max-height:280px;width:auto;max-width:100%" src="'+m.map+'" alt="'+n+'番のホールマップ。下がティー、上がグリーン"></div><p class="note">マップは下がティー、上がグリーンです。</p>':p==='tee'?'<div class="pic"><img src="'+m.tee+'" alt="'+n+'番のティー付近"></div>':'<div class="pic"><img src="'+m.green+'" alt="'+n+'番のグリーン"><span class="tag top">↑奥</span><span class="tag bot">↓手前</span></div><p class="note">旗は撮影時のものです。当日のピンはカートナビかピン位置表で確認します。</p>';return'<div class="tabs">'+[['map','全体'],['tee','ティー'],['green','グリーン']].map(x=>'<button data-pic="'+x[0]+'" aria-pressed="'+(p===x[0])+'">'+x[1]+'</button>').join('')+'</div><div class="pics">'+i+'</div>'}
